function refreshAtLocalMidnight() {
  const now = new Date();
  const next = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 1);
  setTimeout(() => { render(); refreshAtLocalMidnight(); }, next.getTime() - now.getTime());
}
